      },
      {
        "id": "i3",
        "name": "wody",
        "amount": {
          "kind": "exact",
          "value": 300,
          "min": null,
          "max": null,
          "unit": "ml",
          "text": null
        },
        "optional": false,
        "qualifiers": [],
        "sourceText": "300 ml wody"
      }
    ],
    "steps": [
      {
        "id": "s1",
        "text": "Wsyp ryż i groszek do garnka, zalej wodą.",
        "ingredientIds": [
